def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    emit(g.copy(), "Input: 3x3 boxes connected by dotted lines; one box is a checkerboard (the start).")
    boxes = []
    for y in range(H - 2):
        for x in range(W - 2):
            w = g[y:y+3, x:x+3]
            if (w != bg).all():
                boxes.append((y, x))
    boxcells = set()
    for (y, x) in boxes:
        for dy in range(3):
            for dx in range(3):
                boxcells.add((y+dy, x+dx))

    def is_ring(y, x):
        w = g[y:y+3, x:x+3]
        ring = [w[0,0],w[0,1],w[0,2],w[1,0],w[1,2],w[2,0],w[2,1],w[2,2]]
        return len(set(ring)) == 1 and w[1,1] != ring[0]

    start = [b for b in boxes if not is_ring(*b)][0]
    sy, sx = start

    def neighbours_of_box(by, bx):
        out = []
        for y in range(by-1, by+4):
            for x in range(bx-1, bx+4):
                if 0 <= y < H and 0 <= x < W and (y, x) not in boxcells:
                    if (by <= y <= by+2) or (bx <= x <= bx+2):
                        out.append((y, x))
        return out

    seeds = [p for p in neighbours_of_box(sy, sx) if g[p] != bg]
    c = g[seeds[0]]
    seen = set(p for p in seeds if g[p] == c)
    stack = list(seen)
    while stack:
        y, x = stack.pop()
        for dy, dx in ((2,0),(-2,0),(0,2),(0,-2)):
            ny, nx = y+dy, x+dx
            if 0 <= ny < H and 0 <= nx < W and (ny, nx) not in seen \
               and (ny, nx) not in boxcells and g[ny, nx] == c:
                seen.add((ny, nx))
                stack.append((ny, nx))

    trace = g.copy()
    for p in seen:
        trace[p] = c
    emit(trace, f"Follow the dotted path of colour {c} leaving the checkerboard box, ignoring branches of other colours.")

    target = None
    for (by, bx) in boxes:
        if (by, bx) == start:
            continue
        if any(p in seen for p in neighbours_of_box(by, bx)):
            target = (by, bx)
            break
    ty, tx = target
    out = crop(g, ty, tx, ty+2, tx+2)
    emit(out, "The ring box at the end of the same-colour path is the answer; crop it.")
    return out
